+  content: "⚠ ";
+  font-weight: 700;
+}
+
+.form-actions { margin-top: 0.5rem; }
+
+.submit-btn {
+  width: 100%;
+  padding: 0.75rem 1rem;
+  font-size: 1rem;
+  font-weight: 600;
+  color: var(--primary-contrast);
+  background: var(--primary);
+  border: 1px solid var(--primary);
+  border-radius: var(--radius);
+  cursor: pointer;
+  transition: background-color 0.15s ease, transform 0.05s ease;
+  font-family: inherit;
+}
+.submit-btn:hover { background: var(--primary-hover); border-color: var(--primary-hover); }
+.submit-btn:focus { outline: 2px solid var(--focus); outline-offset: 2px; }
+.submit-btn:active { transform: translateY(1px); }
+
+.form-status {
+  margin: 0.25rem 0 0;
+  font-size: 0.95rem;
+  color: #166534;
+  min-height: 1.25rem;
+}
+
+@media (max-width: 480px) {
