+  h1 { font-size: 1.35rem; }
+}
+
+@media (forced-colors: active) {
+  input,
+  .submit-btn,
+  .card {
+    border: 1px solid ButtonBorder;
+  }
+  .submit-btn {
+    background: ButtonFace;
+    color: ButtonText;
+  }
+  input:focus,
+  .submit-btn:focus,
+  .skip-link:focus {
+    outline: 2px solid CanvasText;
+  }
+  .error-message { color: CanvasText; }
+}
